package pe.edu.pucp.admitu.seguridad.impl;
import java.sql.*;import java.util.*;import pe.edu.pucp.admitu.config.*;import pe.edu.pucp.admitu.seguridad.*;import pe.edu.pucp.admitu.seguridad.dao.CuentaUsuarioDAO;
public class CuentaUsuarioImpl implements CuentaUsuarioDAO {
 public CuentaUsuario buscarCorreo(String correo){try(Connection c=DBManager.getInstance().getConnection();CallableStatement s=c.prepareCall("{call BUSCAR_CUENTA_CORREO(?)}")){s.setString(1,correo);try(ResultSet r=s.executeQuery()){return r.next()?new CuentaUsuario(r.getInt("id"),r.getInt("persona_id"),r.getString("correo"),r.getString("rol"),r.getString("clave_hash"),r.getBoolean("activo"),r.getBoolean("bloqueada")):null;}}catch(SQLException e){throw new IllegalStateException("No se pudo consultar la cuenta",e);}}
 public void intento(int id,boolean correcto){try(Connection c=DBManager.getInstance().getConnection();CallableStatement s=c.prepareCall("{call REGISTRAR_INTENTO_CUENTA(?,?)}")){s.setInt(1,id);s.setBoolean(2,correcto);s.execute();}catch(SQLException e){throw new IllegalStateException(e);}}
 public void crearCuenta(int persona,String correo,String rol,String hash){try{Connection c=TransactionContext.getConnection();try(CallableStatement s=c.prepareCall("{call INSERTAR_CUENTA_USUARIO(?,?,?,?)}")){if(persona>0)s.setInt(1,persona);else s.setNull(1,Types.INTEGER);s.setString(2,correo);s.setString(3,rol);s.setString(4,hash);s.execute();}}catch(SQLException e){throw new IllegalStateException(e);}}
 public void crearSesion(String hash,int id){try(Connection c=DBManager.getInstance().getConnection();CallableStatement s=c.prepareCall("{call INSERTAR_SESION_USUARIO(?,?)}")){s.setString(1,hash);s.setInt(2,id);s.execute();}catch(SQLException e){throw new IllegalStateException(e);}}
 public SesionUsuario buscarSesion(String hash){try(Connection c=DBManager.getInstance().getConnection();CallableStatement s=c.prepareCall("{call BUSCAR_SESION_USUARIO(?)}")){s.setString(1,hash);try(ResultSet r=s.executeQuery()){return r.next()?new SesionUsuario(r.getInt("id"),r.getInt("persona_id"),r.getString("correo"),r.getString("rol")):null;}}catch(SQLException e){throw new IllegalStateException(e);}}
 public void eliminarSesion(String hash){try(Connection c=DBManager.getInstance().getConnection();CallableStatement s=c.prepareCall("{call ELIMINAR_SESION_USUARIO(?)}")){s.setString(1,hash);s.execute();}catch(SQLException e){throw new IllegalStateException(e);}}
 public Set<Integer> ids(String recurso,int persona){Set<Integer> ids=new HashSet<>();try(Connection c=DBManager.getInstance().getConnection();CallableStatement s=c.prepareCall("{call LISTAR_IDS_AUTORIZADOS(?,?)}")){s.setString(1,recurso);s.setInt(2,persona);try(ResultSet r=s.executeQuery()){while(r.next())ids.add(r.getInt("id"));}}catch(SQLException e){throw new IllegalStateException(e);}return ids;}
}
